"""Render detected subscriptions as text, JSON, or a self-contained HTML dashboard."""
from __future__ import annotations

import json
from datetime import date
from typing import List

from .detector import Subscription, summarize


def to_dict(subscriptions: List[Subscription]) -> dict:
    return {
        "summary": summarize(subscriptions),
        "subscriptions": [
            {
                "merchant": s.display_name,
                "cadence": s.cadence,
                "typical_amount": s.typical_amount,
                "annualized_cost": s.annualized_cost,
                "total_spent_in_period": s.total_spent,
                "occurrences": s.occurrence_count,
                "first_seen": s.first_seen.isoformat(),
                "last_seen": s.last_seen.isoformat(),
                "next_expected": s.next_expected.isoformat(),
                "likely_cancelled": s.likely_cancelled,
                "price_changes": [
                    {"date": d.isoformat(), "from": old, "to": new}
                    for d, old, new in s.price_changes
                ],
            }
            for s in subscriptions
        ],
    }


def to_json(subscriptions: List[Subscription]) -> str:
    return json.dumps(to_dict(subscriptions), indent=2)


def to_text(subscriptions: List[Subscription]) -> str:
    summary = summarize(subscriptions)
    lines = []
    lines.append("=" * 60)
    lines.append("SubScope Report")
    lines.append("=" * 60)
    lines.append(
        f"Detected {summary['subscription_count']} recurring charge(s), "
        f"{summary['active_count']} still active."
    )
    lines.append(f"Estimated monthly burn:  ${summary['monthly_burn']:.2f}")
    lines.append(f"Estimated annual burn:   ${summary['annual_burn']:.2f}")
    if summary["flagged_price_increases"]:
        lines.append(
            f"⚠ {summary['flagged_price_increases']} subscription(s) had a price change."
        )
    lines.append("")
    for s in subscriptions:
        status = "CANCELLED?" if s.likely_cancelled else "active"
        lines.append(f"- {s.display_name}  [{status}]")
        lines.append(
            f"    {s.cadence}, ~${s.typical_amount:.2f}/charge, "
            f"~${s.annualized_cost:.2f}/yr, seen {s.occurrence_count}x "
            f"({s.first_seen} -> {s.last_seen})"
        )
        if s.price_changes:
            for d, old, new in s.price_changes:
                arrow = "up" if new > old else "down"
                lines.append(f"    price change on {d}: ${old:.2f} -> ${new:.2f} ({arrow})")
        if not s.likely_cancelled:
            lines.append(f"    next charge expected around {s.next_expected}")
        lines.append("")
    return "\n".join(lines)


_HTML_TEMPLATE = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>SubScope Report</title>
<style>
  body {{ font-family: -apple-system, Segoe UI, Roboto, Arial, sans-serif; margin: 2rem; background: #0b0f14; color: #e6edf3; }}
  h1 {{ font-size: 1.6rem; }}
  .summary {{ display: flex; gap: 1rem; flex-wrap: wrap; margin: 1.5rem 0; }}
  .card {{ background: #161b22; border: 1px solid #30363d; border-radius: 10px; padding: 1rem 1.4rem; min-width: 160px; }}
  .card .value {{ font-size: 1.6rem; font-weight: 700; }}
  .card .label {{ color: #8b949e; font-size: 0.8rem; text-transform: uppercase; letter-spacing: .04em; }}
  table {{ width: 100%; border-collapse: collapse; margin-top: 1rem; }}
  th, td {{ text-align: left; padding: 0.6rem 0.8rem; border-bottom: 1px solid #30363d; }}
  th {{ color: #8b949e; font-weight: 600; font-size: 0.82rem; text-transform: uppercase; }}
  tr:hover {{ background: #161b22; }}
  .badge {{ padding: 0.15rem 0.5rem; border-radius: 999px; font-size: 0.75rem; }}
  .badge.active {{ background: #113a24; color: #56d364; }}
  .badge.cancelled {{ background: #3a1e11; color: #e0973c; }}
  .price-up {{ color: #e05555; font-weight: 600; }}
  .muted {{ color: #8b949e; }}
  footer {{ margin-top: 2rem; color: #8b949e; font-size: 0.8rem; }}
</style>
</head>
<body>
<h1>SubScope: Recurring Charges Report</h1>
<div class="summary">
  <div class="card"><div class="value">{subscription_count}</div><div class="label">subscriptions found</div></div>
  <div class="card"><div class="value">${monthly_burn:.2f}</div><div class="label">est. monthly burn</div></div>
  <div class="card"><div class="value">${annual_burn:.2f}</div><div class="label">est. annual burn</div></div>
  <div class="card"><div class="value">{flagged_price_increases}</div><div class="label">price increases flagged</div></div>
</div>
<table>
<thead><tr><th>Merchant</th><th>Status</th><th>Cadence</th><th>Amount</th><th>Annual cost</th><th>Last charged</th><th>Next expected</th><th>Notes</th></tr></thead>
<tbody>
{rows}
</tbody>
</table>
<footer>Generated by SubScope. Heuristic detection based on your CSV export only &mdash; always confirm against your actual bank/card statement before cancelling anything.</footer>
</body>
</html>
"""


def to_html(subscriptions: List[Subscription]) -> str:
    summary = summarize(subscriptions)
    rows = []
    for s in subscriptions:
        status_cls = "cancelled" if s.likely_cancelled else "active"
        status_txt = "Likely cancelled" if s.likely_cancelled else "Active"
        notes = []
        if s.price_changes:
            d, old, new = s.price_changes[-1]
            notes.append(
                f'<span class="price-up">price changed ${old:.2f}&rarr;${new:.2f} on {d}</span>'
            )
        next_expected = "-" if s.likely_cancelled else s.next_expected.isoformat()
        rows.append(
            f"<tr><td>{_esc(s.display_name)}</td>"
            f'<td><span class="badge {status_cls}">{status_txt}</span></td>'
            f"<td>{s.cadence}</td>"
            f"<td>${s.typical_amount:.2f}</td>"
            f"<td>${s.annualized_cost:.2f}</td>"
            f"<td>{s.last_seen.isoformat()}</td>"
            f"<td>{next_expected}</td>"
            f'<td class="muted">{"; ".join(notes) if notes else "&mdash;"}</td></tr>'
        )
    return _HTML_TEMPLATE.format(
        subscription_count=summary["subscription_count"],
        monthly_burn=summary["monthly_burn"],
        annual_burn=summary["annual_burn"],
        flagged_price_increases=summary["flagged_price_increases"],
        rows="\n".join(rows) if rows else "<tr><td colspan='8'>No recurring charges detected.</td></tr>",
    )


def _esc(s: str) -> str:
    return (
        s.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )

